<script>(function(){let token='',items=[],$=id=>document.getElementById(id);function open(){ $('aspiCommitteeModal').hidden=false;loadToken().then(load)}function close(){$('aspiCommitteeModal').hidden=true}async function loadToken(){let r=await fetch('../committee.php?action=csrf&t='+Date.now(),{cache:'no-store'}),j=await r.json();token=j.csrf_token||''}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}function msg(t,ok){let e=$('aspiCommitteeMsg');e.textContent=t;e.style.color=ok?'#16a34a':'#dc2626'}async function load(){let r=await fetch('../committee.php?action=list&admin=1&t='+Date.now(),{cache:'no-store'}),j=await r.json();items=j.committee||[];render()}function render(){let b=$('aspiCommitteeList');b.innerHTML='';if(!items.length){b.innerHTML='<div class="col-span-full text-sm font-bold text-slate-500 py-8 text-center border border-dashed rounded-2xl">কোনো সদস্য যোগ করা হয়নি।</div>';return}items.forEach(m=>{let e=document.createElement('div');e.className='rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 p-4';e.innerHTML='<div class="flex gap-3"><div class="w-16 h-16 rounded-full overflow-hidden bg-slate-100 dark:bg-slate-700 shrink-0">'+(m.image_url?'<img src="../'+esc(m.image_url)+'" class="w-full h-full object-cover">':'<div class="w-full h-full flex items-center justify-center"><i class="fa-solid fa-user-tie text-slate-400"></i></div>')+'</div><div class="min-w-0"><div class="font-black truncate">'+esc(m.name_bn||m.name_en)+'</div><div class="text-xs text-slate-500 mt-1">'+esc(m.designation_bn||m.designation_en)+'</div><span class="inline-block mt-2 text-[10px] font-black px-2 py-1 rounded bg-slate-100 dark:bg-slate-700">'+(m.status?'Published':'Hidden')+'</span></div></div><div class="flex gap-2 mt-3"><button class="admin-btn admin-btn-primary inline-auto text-xs" data-edit="'+m.id+'">Edit</button><button class="admin-btn admin-btn-danger inline-auto text-xs" data-del="'+m.id+'">Delete</button></div>';b.appendChild(e)});b.querySelectorAll('[data-edit]').forEach(x=>x.onclick=()=>edit(+x.dataset.edit));b.querySelectorAll('[data-del]').forEach(x=>x.onclick=()=>del(+x.dataset.del))}function reset(){$('committee_id').value='';['committee_name_bn','committee_name_en','committee_designation_bn','committee_designation_en'].forEach(id=>$(id).value='');$('committee_image').value='';$('committee_status').checked=true;$('committee_sort').value=0;msg('',true)}function edit(id){let m=items.find(x=>+x.id===id);if(!m)return;$('committee_id').value=m.id;$('committee_name_bn').value=m.name_bn||'';$('committee_name_en').value=m.name_en||'';$('committee_designation_bn').value=m.designation_bn||'';$('committee_designation_en').value=m.designation_en||'';$('committee_status').checked=!!+m.status;$('committee_sort').value=m.sort_order||0}async function upload(f){if(!f)return '';let fd=new FormData();fd.append('file',f);fd.append('csrf_token',token);let r=await fetch('../committee.php?action=upload',{method:'POST',body:fd}),j=await r.json();if(!j.url)throw Error(j.error||'Upload failed');return j.url}$('aspiCommitteeOpen')?.addEventListener('click',open);$('aspiCommitteeClose')?.addEventListener('click',close);$('aspiCommitteeRefresh')?.addEventListener('click',load);$('aspiCommitteeReset')?.addEventListener('click',reset);$('aspiCommitteeForm')?.addEventListener('submit',async e=>{e.preventDefault();try{let old=items.find(x=>+x.id===+$('committee_id').value),image=old?.image_url||'';if($('committee_image').files[0])image=await upload($('committee_image').files[0]);let p={csrf_token:token,id:+$('committee_id').value||0,name_bn:$('committee_name_bn').value,name_en:$('committee_name_en').value,designation_bn:$('committee_designation_bn').value,designation_en:$('committee_designation_en').value,image_url:image,status:$('committee_status').checked?1:0,sort_order:+$('committee_sort').value||0};let r=await fetch('../committee.php?action=save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)}),j=await r.json();if(j.status!=='success')throw Error(j.error||'Save failed');msg('সংরক্ষণ সম্পন্ন হয়েছে।',true);reset();load()}catch(x){msg(x.message,false)}});async function del(id){if(!confirm('এই সদস্যকে মুছে ফেলবেন?'))return;let r=await fetch('../committee.php?action=delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf_token:token,id})}),j=await r.json();if(j.status==='success')load();else msg(j.error||'Delete failed',false)}})();</script>
